var json_TITIKBUDAYAKAWASANKOTATUAPADANG_7 = {"type":"FeatureCollection","name":"TITIKBUDAYAKAWASANKOTATUAPADANG_7","crs":{"type":"name","properties":{"name":"urn:ogc:def:crs:OGC:1.3:CRS84"}},"features":[{"type":"Feature","properties":{"fid":"1","Kategori":"Cagar Budaya 1","Nama_Awal":"-","Masa trans":"Kantor PU TK. I Cipta Karya","bangunan s":"Kantor Dinas Prasjal dan Tarkim Provinsi Sumatera Barat","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"13","no iventra":"23/BCB-TB/A/01/2007","tahun ber":"Abad ke-19 dan ke-20","kepemilika":"Pemerintah Provinsi Sumatera Barat","pengelolaa":"Tidak ada pengelola aktif di lokasi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\PT. CIPTA KARYA.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\plakat PT. Cipta Karya.jpeg","Foto Tradi":null,"Alamat":"Jl. Batang Arau No.38","kelurahan":"Berok Nipah ","kecamatan":"Padang Barat","Bujur":"100°21'20.07\"BT", "Lintang": "0°57'56.07\"LS","Longitude_":100.35558,"Langitude_":-0.96558,"Fungsi Bangunan":"Eks Kantor PU Provinsi (Tidak berfungsi)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Kantor Dinas Prasjal dan Tarkim Provinsi Sumatera Barat merupakan bangunan peninggalan kolonial Hindia Belanda yang awalnya berfungsi sebagai kantor Burgerlijke Openbare Werken (BOW) atau Dinas Pekerjaan Umum Sipil. Setelah Indonesia merdeka, bangunan ini digunakan sebagai Kantor Tata Pemukiman, kemudian menjadi Kantor PU TK. I Cipta Karya Provinsi Sumatera Barat, dan selanjutnya dikenal sebagai Kantor Dinas Prasjal dan Tarkim Provinsi Sumatera Barat. Bangunan ini sempat mengalami kerusakan akibat gempa 30 September 2009 dan telah direhabilitasi. Saat ini gedung tidak lagi difungsikan, berada dalam kondisi kosong dan kurang terawat. Meskipun demikian, fasad dan beberapa elemen arsitektur kolonialnya masih terjaga sehingga tetap memiliki nilai sejarah sebagai salah satu bangunan cagar budaya di kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini telah mengalami beberapa perubahan pada bagian depan, terutama berupa penambahan teras dengan atap seng serta perubahan bentuk atap. Bagian samping kanan dan kiri bangunan masih mempertahankan bentuk aslinya. Atap bangunan yang sebelumnya menggunakan genteng telah diganti dengan seng berbentuk limas yang memanjang ke bagian belakang, meskipun bentuknya juga telah mengalami sedikit perubahan. Pada bagian depan terdapat dinding yang menjulang ke atas dengan bukaan berupa jendela angin-angin. Secara keseluruhan, karakter arsitektur bangunan masih menunjukkan ciri bangunan kolonial Belanda. Perubahan juga terjadi pada bagian interior serta sebagian bentuk atap, namun elemen arsitektur pada bagian samping masih relatif mempertahankan bentuk aslinya.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.355575,-0.965575]}},{"type":"Feature","properties":{"fid":"2","Kategori":"Cagar Budaya 2","Nama_Awal":"-","Masa trans":"Kantor Pemasaran Pertamina/Eks. Kantor PT Hiswana","bangunan s":"Yoga / Aerobik","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"14","no iventra":"41/BCB-TB/A/01/2007","tahun ber":"1929","kepemilika":"BUMN/Pertamina","pengelolaa":"Tidak Ada Pengelola yang Aktif di lokasi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\PT PERTAMINA.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat PT. Pertamina.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.78","kelurahan":"Berok Nipah","kecamatan":"Padang Barat ","Bujur":"100°21'23.43\"BT", "Lintang": "0°57'55.72\"LS","Longitude_":100.35651,"Langitude_":-0.96548,"Fungsi Bangunan":"Bangunan Kosong","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Kantor PT. Hiswana/Pertamina merupakan bangunan cagar budaya yang didirikan pada tahun 1929 pada masa kolonial Belanda. Awalnya bangunan ini difungsikan sebagai kantor dan menjadi bagian dari kawasan perdagangan di sepanjang Jalan Batang Arau. Saat ini bangunan sudah tidak lagi dimanfaatkan dan berada dalam kondisi kosong.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini terdiri atas dua lantai dengan denah berbentuk persegi panjang yang memanjang ke belakang. Bentuk bangunan memberikan kesan ramping dan tinggi serta menggunakan atap genteng berbentuk limas terpancung. Fasad depan didominasi oleh lima jendela kaca nako berukuran besar,yang terdiri atas tiga jendela di lantai atas dan dua jendela di lantai bawah. Pintu utama terletak di bagian tengah fasad dan diapit oleh jendela di sisi kiri dan kanan. Meskipun tata ruang bagian dalam telah mengalami perubahan, karakter arsitektur eksterior bangunan masih tetap dipertahankan.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.356508,-0.965478]}},{"type":"Feature","properties":{"fid":"3","Kategori":"Cagar Budaya 3","Nama_Awal":"Okupasi / WNA Tionghua","Masa trans":"Kantor Detasemen Pembekalan AD","bangunan s":"Kantor Detasemen Pembekalan AD","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"15","no iventra":"22/BCB-TB/A/01/2007","tahun ber":"Akhir Abad ke-19","kepemilika":"Negara/TNI AD-Kodam I Bukit Barisan","pengelolaa":"Tidak ada pengelola aktif di lokasi","kondisi fi":"Rusak Parah","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_TNI.png","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_TNI.jpg","Foto Tradi":null,"Alamat":"Jl. Batang Arau No.76","kelurahan":"Berok Nipah","kecamatan":"Padang Barat","Bujur":"100°21'24.31\"BT", "Lintang": "0°57'55.57\"LS","Longitude_":100.35675,"Langitude_":-0.96544,"Fungsi Bangunan":"Bangunan Kosong","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung ini merupakan peninggalan masa kolonial Hindia Belanda yang pada awalnya difungsikan sebagai kantor, rumah tinggal, dan gudang. Dalam perjalanan sejarahnya, gedung ini pernah digunakan sebagai Gedung Okupasi Warga Negara Asing (WNA) Tionghoa sebelum kemudian menjadi bagian dari kompleks Detasemen Pembekalan Angkatan Darat 1-44-05 TNI AD. Akibat gempa bumi 30 September 2009, bangunan mengalami kerusakan berat. Hingga saat ini gedung tidak lagi difungsikan dan sebagian atapnya telah runtuh. Kondisi tersebut menyebabkan tingkat kerusakan terus meningkat sehingga berpotensi mengancam keutuhan struktur dan fasad apabila tidak segera dilakukan upaya pelestarian.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Kantor Bagian Pengadaan dan Transportasi terdiri atas tiga bangunan yang memiliki keterkaitan dalam tata letak dan karakter arsitekturnya. Berdasarkan bentuk denah dan susunan ruang, bangunan ini diperkirakan pada awalnya berfungsi sebagai tempat tinggal. Dua bangunan berada di sisi selatan dan tersusun berjejer di belakang bangunan utama yang terletak di sisi utara. Bangunan utama di bagian utara memiliki denah berbentuk persegi dengan atap berbentuk limasan yang menggunakan penutup genteng. Fasad bangunan memperlihatkan karakter arsitektur Art Deco yang ditandai oleh bentuk kubus, penggunaan struktur beton, serta minimnya ornamen dekoratif. Tata ruang bangunan juga menunjukkan karakter bangunan hunian. Setelah dialihfungsikan menjadi kantor bagian pengadaan dan transportasi, ruang keluarga dibagi menjadi tiga sekat menggunakan material kayu lapis dan seluruh ruang kemudian dimanfaatkan sebagai ruang kerja. Secara umum, komponen arsitektur bangunan masih mempertahankan bentuk aslinya. Kondisi bangunan mengalami kerusakan cukup berat akibat gempa bumi tahun 2009. Setelah kejadian tersebut, bangunan tidak lagi digunakan. Kerusakan terlihat pada dinding yang mengalami retak dan pengelupasan plester, sedangkan bagian dinding atas mengalami pergeseran dan kemiringan. Selain itu, beberapa bagian plafon dan rangka atap mengalami keruntuhan. Bangunan belakang yang berjarak sekitar 1,5 meter dari bangunan utama juga mengalami kerusakan berat. Diperkirakan sekitar 80% bagian bangunan rusak akibat gempa. Kondisi yang tersisa saat ini berupa sebagian dinding bata dengan ketinggian sekitar 150 cm, sedangkan bagian atap dan sebagian besar struktur bangunan telah runtuh dan tidak lagi utuh.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.356752999999898,-0.965436]}},{"type":"Feature","properties":{"fid":"4","Kategori":"Cagar Budaya 4","Nama_Awal":"Gudang PT. Pataka Karya Sentosa","Masa trans":"Kerambia Cafe","bangunan s":"Angels Wing","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"17","no iventra":"39/BCB-TB/A/01/2007","tahun ber":"1933","kepemilika":"Swasta","pengelolaa":"Manajemen Angels Wing Padang","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\PT Pataka.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Pelakat PT. Pataka.jpg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.70","kelurahan":"Berok Nipah","kecamatan":"Padang Barat","Bujur":"100°21'26.90\"BT", "Lintang": "0°57'54.43\"LS","Longitude_":100.35747,"Langitude_":-0.96512,"Fungsi Bangunan":"Tempat Hiburan Malam","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Eks Gudang PT. Pataka Karya Sentosa merupakan salah satu bangunan cagar budaya di Kawasan Kota Tua Padang yang pada masa kolonial Belanda digunakan sebagai gudang penyimpanan untuk mendukung aktivitas perdagangan di kawasan Pelabuhan Muara Padang. Setelah Indonesia merdeka, bangunan dimanfaatkan sebagai gudang operasional PT. Pataka Karya Sentosa. Seiring perkembangan kawasan, fungsi bangunan mengalami perubahan dan saat ini telah dialihfungsikan menjadi Angel's Wing, sebuah tempat usaha di bidang kuliner dan hiburan. Meskipun telah mengalami perubahan fungsi, bangunan ini tetap eksis sebagai bagian dari warisan sejarah Kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Secara arsitektural, bangunan ini merupakan bangunan bergaya kolonial yang memiliki bentuk atap limasan. Pada bagian dinding bangunan terdapat 10 jendela, terdiri atas tiga jendela pada sisi kiri, tiga pada sisi kanan, dan empat pada bagian depan. Jendela berukuran relatif tinggi dan lebar menggunakan kaca dengan rangka logam. Pintu masuk utama terletak di bagian tengah dan sedikit menjorok ke arah depan bangunan. Setelah gempa bumi tahun 2009, bangunan mengalami kerusakan ringan pada beberapa bagian. Saat ini, bangunan sedang dalam proses renovasi, baik pada bagian fasad maupun interior. Renovasi tersebut dilakukan untuk menyesuaikan bangunan dengan rencana pemanfaatan baru sebagai restoran atau kedai kopi. Meskipun mengalami perubahan fungsi dan renovasi, karakter arsitektur kolonial pada bangunan masih dapat dikenali.</p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p></body></html>"},"geometry":{"type":"Point","coordinates":[100.357472,-0.965119]}},{"type":"Feature","properties":{"fid":"5","Kategori":"Cagar Budaya 5","Nama_Awal":"De Javas Bank","Masa trans":"Bank Indonesia","bangunan s":"Museum Bank Indonesia Muaro Padang","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"18","no iventra":"38/BCB-TB/A/01/2007","tahun ber":"1864","kepemilika":"Bank Indonesia","pengelolaa":"Bank Indonesia","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\museum.jpeg","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat museum.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.66","kelurahan":"Berok Nipah","kecamatan":"Padang Barat","Bujur":"100°21'30.23\"BT", "Lintang": "0°57'52.47\"LS","Longitude_":100.3584,"Langitude_":-0.96458,"Fungsi Bangunan":"Museum Bank Indonesia","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Bank Indonesia Muaro Padang pada masa Hindia Belanda dikenal sebagai De Javasche Bank (DJB) Cabang Padang. Bangunan ini berfungsi sebagai kantor cabang De Javasche Bank yang menjadi salah satu pusat aktivitas keuangan di kawasan Muaro Batang Arau. De Javasche Bank Cabang Padang merupakan cabang ketiga setelah Surabaya dan Semarang serta menjadi cabang pertama De Javasche Bank yang didirikan di luar Pulau Jawa. Pembangunan gedung baru dimulai pada 31 Maret 1921 dan selesai pada tahun 1925, menggantikan kantor lama De Javasche Bank yang sebelumnya berada di kawasan Jalan Nipah. Setelah proses nasionalisasi perbankan, gedung ini kemudian diambil alih oleh Bank Indonesia pada 1 Juli 1953 dan difungsikan sebagai Kantor Perwakilan Bank Indonesia hingga tahun 1977. Selanjutnya, aktivitas perkantoran Bank Indonesia dipindahkan ke gedung baru di Jalan Jenderal Sudirman, sementara bangunan lama tetap memiliki nilai sejarah sebagai salah satu peninggalan arsitektur kolonial dan perkembangan sistem perbankan di Kota Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Bank Indonesia Muaro Padang memiliki gaya arsitektur Indonesia modern tropis yang menyesuaikan karakter bangunan kolonial dengan kondisi iklim tropis. Bangunan berbentuk persegi panjang dengan atap piramida yang menyerupai bentuk atap masjid dan dilengkapi dengan kubah pada bagian puncaknya. Atap bangunan menggunakan material ubin yang menjadi ciri khas arsitektur pada masa tersebut. Pintu masuk utama berada di bagian tengah fasad depan yang menghadap ke arah timur. Pada bagian dinding bangunan terdapat jendela-jendela kaca dengan bingkai baja berbentuk tinggi dan ramping untuk mendukung sirkulasi udara serta pencahayaan alami. Fasad depan memiliki sembilan jendela, sedangkan sisi samping bangunan terdiri atas empat jendela dengan bentuk serupa. Hingga saat ini, bangunan tersebut masih terawat dengan baik dan mempertahankan karakter arsitektur aslinya sebagai salah satu peninggalan bersejarah di kawasan Muaro Batang Arau, Kota Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.358396999999897,-0.964575]}},{"type":"Feature","properties":{"fid":"6","Kategori":"Cagar Budaya 6","Nama_Awal":"Geo Wehry & Co","Masa trans":"Gudang PT. Panca Niaga","bangunan s":"Aw Billiard Padang","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"20","no iventra":"21/BCB-TB/A/01/2007","tahun ber":"1920","kepemilika":"PT. Persero","pengelolaa":"PT. Persero","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Geo Wehry & Co.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat PT. Panca Niaga.jpg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.58","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat ","Bujur":"100°21'33.99\"BT", "Lintang": "0°57'52.00\"LS","Longitude_":100.35944,"Langitude_":-0.96444,"Fungsi Bangunan":"Tempat olahraga dan rekreasi (biliar)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Geo Wehry &amp; Co merupakan salah satu bangunan cagar budaya ikonik di Kawasan Kota Tua Padang. Dibangun pada awal abad ke-20, gedung ini awalnya berfungsi sebagai kantor dan gudang milik NV Geo Wehry &amp; Co, salah satu perusahaan dagang besar Hindia Belanda yang bergerak dalam perdagangan hasil perkebunan dari pedalaman Minangkabau. Setelah Indonesia merdeka, aset perusahaan dinasionalisasi dan dikelola oleh PT Perusahaan Perdagangan Indonesia, kemudian dimanfaatkan sebagai gudang. Pada November 2022, gedung ini direvitalisasi dengan menerapkan konsep adaptive reuse untuk menghidupkan kembali fungsi bangunan tanpa menghilangkan nilai sejarah dan karakter arsitekturnya. Setelah direvitalisasi, bangunan ini sempat dimanfaatkan sebagai restoran dan kafe. Saat ini, Gedung Geo Wehry &amp; Co difungsikan sebagai tempat biliar, sehingga tetap menjadi salah satu bangunan bersejarah yang aktif dimanfaatkan di Kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Geo Wehry &amp; Co merupakan bangunan bergaya arsitektur kolonial modern yang dirancang oleh arsitek Belanda F.J.L. Ghijsels. Bangunan ini memiliki bentuk yang simetris dengan dinding pasangan bata yang kokoh, jendela-jendela berukuran besar, serta bukaan yang dirancang untuk memaksimalkan pencahayaan dan sirkulasi udara. Fasad bangunan menampilkan garis-garis geometris yang sederhana dengan minim ornamen, mencerminkan karakter arsitektur modern awal abad ke-20. Meskipun telah mengalami revitalisasi dan perubahan fungsi, bentuk utama, fasad, serta karakter arsitekturnya masih dipertahankan sehingga tetap mencerminkan nilai sejarah sebagai salah satu bangunan cagar budaya di Kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.359441999999888,-0.964444]}},{"type":"Feature","properties":{"fid":"7","Kategori":"Cagar Budaya 7","Nama_Awal":"-","Masa trans":"PT. Dharma Niaga-BPD-CV-Purwasari","bangunan s":"Halim Badminton Hall","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"21","no iventra":"20/BCB-TB/A/01/2007","tahun ber":"Abad ke-19","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\pt dhara.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\plakat d.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.48","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat ","Bujur":"100°21'35.01\"BT", "Lintang": "0°57'51.07\"LS","Longitude_":100.35973,"Langitude_":-0.96419,"Fungsi Bangunan":"Gedung olahraga (lapangan bulu tangkis/Halim Badminton Hall)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan PT. Dharma Niaga yang kini dikenal sebagai Halim Badminton Hall diperkirakan dibangun pada awal tahun 1900-an. Awalnya, bangunan ini merupakan rumah tinggal milik masyarakat keturunan Tionghoa yang kemudian dimanfaatkan sebagai bangunan komersial. Keberadaannya menjadi bagian dari perkembangan kawasan perdagangan di Kota Tua Padang. Setelah tidak lagi digunakan sebagai kantor PT. Dharma Niaga, bangunan ini beralih fungsi dan saat ini dimanfaatkan sebagai Halim Badminton Hall.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan PT. Dharma Niaga/CV. Purwasari telah mengalami renovasi yang cukup signifikan pada hampir seluruh bagian bangunan, baik dari segi bentuk, tata ruang interior, maupun fungsi. Bangunan terdiri atas dua lantai, dengan lantai pertama yang sebelumnya berfungsi sebagai gudang dan saat ini digunakan untuk mendukung aktivitas Halim Hall Badminton, sedangkan lantai kedua dimanfaatkan sebagai lapangan badminton. Perubahan paling signifikan terdapat pada lantai pertama berupa penambahan struktur dan fondasi untuk menyesuaikan bangunan dengan fungsi barunya. Pada lantai kedua juga dilakukan penambahan ketinggian tiang atau struktur penyangga guna memenuhi kebutuhan ruang sebagai fasilitas olahraga. Perubahan tersebut menyebabkan bentuk bangunan saat ini cukup berbeda dibandingkan dengan bentuk bangunan sebelumnya. Dari aspek pelestarian, kondisi bangunan saat ini kurang memperhatikan kaidah konservasi bangunan bersejarah. Dinding bagian luar telah mengalami pelapisan ulang dan dilengkapi dengan elemen dekoratif berupa lukisan dinding berbentuk persegi panjang dan segitiga. Pada bagian depan terdapat beberapa jendela sebagai elemen bukaan. Secara keseluruhan, bangunan dalam kondisi kurang terawat dan telah mengalami perubahan fisik yang cukup besar sehingga karakter bangunan aslinya relatif sulit dikenali.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.359724999999884,-0.964186]}},{"type":"Feature","properties":{"fid":"8","Kategori":"Cagar Budaya 8","Nama_Awal":"-","Masa trans":"Gudang Minangcaisa","bangunan s":"Nangkring Galodo'88","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"22","no iventra":"19/BCB-TB/A/01/2007","tahun ber":"Abad Ke-19","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Gudang Minangcaisa.jpeg","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat Gudang Minangcaisa.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.50","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'36.25\"BT", "Lintang": "0°57'51.17\"LS","Longitude_":100.36007,"Langitude_":-0.96421,"Fungsi Bangunan":"Pusat kuliner","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gudang Minangcaisa merupakan salah satu bangunan bersejarah di Kawasan Kota Tua Padang yang dibangun pada masa kolonial Belanda sebagai gudang penyimpanan barang dagangan. Keberadaan gudang ini berkaitan dengan aktivitas perdagangan di kawasan pelabuhan Muara Padang yang pada saat itu menjadi pusat distribusi berbagai komoditas ekspor dan impor. Seiring berjalannya waktu, fungsi bangunan mengalami perubahan mengikuti perkembangan kawasan. Saat ini, Gudang Minangcaisa telah dialihfungsikan menjadi Nangkring Galodo '88, namun bentuk utama bangunan masih dipertahankan sebagai bagian dari upaya pelestarian bangunan bersejarah di Kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gudang Minangcaisa telah mengalami renovasi, namun bentuk fasadnya tetap dirancang menyerupai bangunan asli. Meskipun demikian, terdapat beberapa perubahan pada elemen arsitektur, seperti bentuk kepala bangunan, desain jendela di sisi kiri dan kanan, serta penambahan kanopi pada pintu masuk. Fasad bangunan didominasi oleh pilar-pilar berlapis plester berbentuk persegi yang dipadukan dengan bukaan semu berbentuk lengkung pada bagian atas, sehingga masih menampilkan karakter bangunan kolonial meskipun telah mengalami penyesuaian pada beberapa bagian.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.360068999999882,-0.964214]}},{"type":"Feature","properties":{"fid":"9","Kategori":"Cagar Budaya 9","Nama_Awal":"Nederlands Indishe Escomto NV","Masa trans":"PT. Bank Dagang Negara","bangunan s":"Bank Mandiri","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"25","no iventra":"17/BCB-TB/A/01/2007","tahun ber":"1939","kepemilika":"BUMN","pengelolaa":"BUMN","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Gambar Bank Mandiri.jpeg","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat Bank Mandiri.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.42","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'39.28\"BT", "Lintang": "0°57'49.89\"LS","Longitude_":100.36091,"Langitude_":-0.96386,"Fungsi Bangunan":"Bank Mandiri","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini merupakan bangunan bergaya arsitektur kolonial Belanda yang terletak di kawasan Batang Arau, Kota Tua Padang. Dibangun sekitar tahun 1939, gedung ini awalnya merupakan kantor Nederlandsch-Indische Escompto Maatschappij (NIEM) salah satu bank tertua di Hindia Belanda yang didirikan di Batavia pada tahun 1857. Pada tahun 1949 nama bank berubah menjadi  Escomptobank NV, kemudian dinasionalisasi oleh pemerintah Indonesia pada tahun 1960 dan berganti nama menjadi Bank Dagang Negara. Saat ini bangunan tersebut masih difungsikan sebagai kantor Bank Mandiri Muaro dan telah ditetapkan sebagai bangunan cagar budaya.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini merupakan bangunan berarsitektur kolonial Belanda yang memiliki karakter khas berupa pintu dan jendela berukuran tinggi. Atap bangunan menggunakan penutup genteng dan memiliki bentuk bertingkat menyerupai susunan dua bagian atap. Pintu masuk utama terletak di bagian tengah bangunan dan dilengkapi balkon dengan struktur atap beton. Posisi pintu dan area masuk yang sedikit menonjol memberikan kesan bangunan bertingkat dua, meskipun berdasarkan susunan jendela pada bagian luar, bangunan sebenarnya hanya terdiri atas satu lantai. Pada awalnya, bangunan yang berfungsi sebagai kantor perbankan memiliki ruang dalam yang relatif terbuka. Seiring dengan perkembangan fungsi bangunan, ruang interior kemudian dibagi menjadi beberapa ruangan menggunakan partisi yang bersifat tidak permanen. Pada bagian tengah terdapat langit-langit yang memiliki struktur memanjang ke arah luar. Bagian atas dinding, tepat di bawah langit-langit, dilengkapi dengan jendela kaca dan rangka besi. Pada setiap sudut langit-langit terdapat elemen besi yang berfungsi sebagai struktur penahan dan saling terhubung menggunakan baut dengan konstruksi yang menyerupai sambungan pada tiang kayu. Pasca gempa bumi tahun 2009, bangunan mengalami kerusakan ringan sekitar 10%, terutama berupa retakan pada dinding bagian depan. Sementara itu, bagian depan ruang dalam tidak mengalami kerusakan berarti. Secara keseluruhan, bangunan masih dalam kondisi baik dan relatif terawat, serta karakter arsitektur kolonialnya masih dapat dikenali.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.360910999999888,-0.963858]}},{"type":"Feature","properties":{"fid":"10","Kategori":"Cagar Budaya 10","Nama_Awal":"-","Masa trans":"Toko Clarity Audio","bangunan s":"PT. Kurnia Jagad Abadi","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"28","no iventra":"35/BCB-TB/A/01/2007","tahun ber":"Awal Abad ke-20","kepemilika":"PT. Kurnia Jagad Abadi","pengelolaa":"PT. Kurnia Jagad Abadi","kondisi fi":"Rusak Parah","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Gudang (2).jfif","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat.jfif","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.24","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'45.01\"BT", "Lintang": "0°57'47.00\"LS","Longitude_":100.3625,"Langitude_":-0.96306,"Fungsi Bangunan":"Bangunan Kosong","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Eks PT. Kurnia Jagad Abadi merupakan salah satu bangunan cagar budaya di Kawasan Kota Tua Padang yang diperkirakan dibangun pada awal abad ke-20, sekitar tahun 1910. Bangunan ini berada di Jalan Batang Arau No. 24, Kelurahan Kampung Pondok. Hingga kini tidak ditemukan dokumen atau literatur yang menjelaskan secara pasti fungsi awal maupun sejarah pendirian perusahaan tersebut. Beberapa hasil inventarisasi cagar budaya hanya menyebutkan bahwa sejak awal bangunan ini digunakan sebagai tempat kegiatan perdagangan atau perniagaan. Dalam perkembangannya, bangunan ini pernah dimanfaatkan sebagai agen penyalur LPG, toko material bangunan, toko papan bunga, dan dikenal pula sebagai bekas Toko Clarity Audio. Namun, berdasarkan hasil observasi lapangan terbaru, bangunan tersebut saat ini sudah tidak lagi difungsikan dan berada dalam kondisi kosong. Kondisi fisiknya mengalami kerusakan berat, terutama pada bagian lantai dua yang dilaporkan nyaris roboh sehingga menjadi salah satu bangunan cagar budaya yang memerlukan perhatian pelestarian.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini terdiri atas dua unit bangunan yang memiliki karakter arsitektur berbeda, tetapi masih berada dalam satu kesatuan kawasan. Bangunan pertama memiliki teras pada bagian lantai bawah. Pada lantai atas terdapat serambi yang mengelilingi keempat sisi bangunan. Bagian tepi serambi dilengkapi dengan dinding berupa jeruji kayu yang menjadi salah satu elemen khas bangunan. Fungsi awal bangunan ini belum diketahui secara pasti. Dalam perkembangannya, bangunan kemudian dimanfaatkan sebagai ruang pamer atau toko elektronik.</p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p>\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan kedua memiliki bentuk yang menyerupai rumah panggung. Akses masuk berada pada lantai bawah melalui dua pintu yang terletak di sisi kanan dan kiri bangunan. Bukaan pada lantai bawah berupa jendela yang berfungsi sebagai ventilasi dan dilengkapi dengan jeruji besi, sedangkan jendela pada lantai atas juga menggunakan jeruji besi. Pada bagian lantai atas terdapat serambi yang mengelilingi bangunan dan dilengkapi pagar atau dinding kayu berjeruji pada bagian luarnya. Fungsi awal bangunan belum diketahui secara pasti. Berdasarkan bentuk dan tata ruangnya, bangunan diperkirakan pada awalnya memiliki fungsi ganda, yaitu bagian bawah sebagai gudang dan bagian atas sebagai tempat tinggal. Saat ini, salah satu bangunan masih dimanfaatkan sebagai gudang dan toko, sedangkan bangunan lainnya sudah tidak difungsikan dan kondisinya kurang terawat. Berdasarkan karakter arsitektur dan tingkat keasliannya, bangunan ini termasuk dalam kategori Tipe B serta memiliki potensi untuk dipertahankan dan dilestarikan sebagai bagian dari warisan arsitektur kawasan.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.36250299999989,-0.963056]}},{"type":"Feature","properties":{"fid":"11","Kategori":"Cagar Budaya 11","Nama_Awal":"Spaar Bank","Masa trans":"Beautik Hotel","bangunan s":"Padangsche Spaarbank","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"29","no iventra":"16/BCB-TB/A/01/2007","tahun ber":"1908","kepemilika":"Pribadi ","pengelolaa":"Pribadi ","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Spaak Bank.png","foto plaka":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\Plakat Spaar Bank.jfif","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.33","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'46.33\"BT", "Lintang": "0°57'47.70\"LS","Longitude_":100.36287,"Langitude_":-0.96325,"Fungsi Bangunan":"Cafe","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Padangsche Spaarbank didirikan pada tahun 1908 sebagai kantor Padangsche Spaarbank, sebuah bank tabungan pada masa pemerintahan kolonial Belanda. Setelah Indonesia merdeka, bangunan ini pernah digunakan sebagai Bank Tabungan Sumatera Barat. Seiring perkembangan kawasan Batang Arau sebagai destinasi wisata sejarah, fungsi bangunan kemudian berubah menjadi kafe dan penginapan (Beautique Hotel) dengan tetap mempertahankan bentuk fasad serta karakter arsitektur kolonialnya. Perubahan fungsi tersebut merupakan bentuk adaptasi pemanfaatan bangunan cagar budaya agar tetap lestari dan memiliki nilai ekonomi tanpa menghilangkan nilai sejarah yang dimilikinya.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan Padangsche Spaarbank merupakan bangunan dua lantai dengan tinggi sekitar 35 meter yang berada di tepi Sungai Batang Arau. Dibangun pada tahun 1908, bangunan ini mengusung perpaduan gaya Neo-Klasik dan Art Deco yang terlihat pada fasad simetris, dinding masif khas bangunan kolonial, serta bukaan pintu dan jendela berukuran besar. Ornamen horizontal, lengkungan pada bukaan, dan mahkota bangunan dengan penanda tahun pembangunan menjadi ciri arsitektural yang memperkuat karakter bangunan. Pada masa kolonial, bangunan ini berfungsi sebagai bank tabungan, kemudian beralih fungsi menjadi hotel. Akibat gempa bumi tahun 2009, bangunan mengalami kerusakan pada sekitar 40% bagiannya, terutama berupa retakan pada dinding dan lantai. Setelah dilakukan perbaikan dan penataan, bangunan kembali dimanfaatkan. Berdasarkan hasil observasi lapangan, bangunan saat ini telah beralih fungsi menjadi kafe, dengan tetap mempertahankan bentuk fasad serta karakter arsitektur kolonialnya sebagai salah satu bangunan cagar budaya di Kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.36286899999989,-0.96325]}},{"type":"Feature","properties":{"fid":"12","Kategori":"Cagar Budaya 12","Nama_Awal":"Gedung Eng Tjoan Tong","Masa trans":"Himpunan Keluarga Tan ","bangunan s":"Himpunan Keluarga Tan ","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"32","no iventra":"43/BCB-TB/A/01/2007","tahun ber":"1888","kepemilika":"Himpunan Keluarga Tan","pengelolaa":"Himpunan Keluarga Tan","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\JURNAL\\New folder\\tan (1).jpg","foto plaka":"Tidak ditemukan plakat di lapangan","Foto Tradi":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_Perayan tan.png","Alamat":"Jl.  Kelenteng No.327","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'43.32\"BT", "Lintang": "0°57'44.50\"LS","Longitude_":100.36203,"Langitude_":-0.96236,"Fungsi Bangunan":"Gedung Organisasi Sosial  dan Kekeluargaan","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Himpunan Keluarga Tan atau yang dahulu dikenal sebagai Gedung Eng Tjoan Tong (Eng Cuan Tong) merupakan organisasi perkumpulan keluarga masyarakat Tionghoa bermarga Tan di Kota Padang. Organisasi ini didirikan pada 22 Maret 1888 oleh Cinang Tan Siang bersama beberapa anggota keluarga Tan lainnya di kawasan Muara Padang. Pendirian himpunan ini dilandasi oleh nilai kekeluargaan, kebersamaan, dan gotong royong untuk mempererat hubungan antaranggota marga Tan. Pada awal perkembangannya, Gedung Eng Tjoan Tong berfungsi sebagai tempat perkumpulan sosial, kegiatan budaya, serta ruang pelaksanaan kegiatan keagamaan masyarakat Tionghoa. Organisasi ini berperan dalam memberikan bantuan sosial kepada anggota keluarga Tan, terutama dalam kegiatan kemanusiaan seperti bantuan ketika mengalami kesulitan, kematian, dan proses pemakaman. Dalam perkembangannya, Himpunan Keluarga Tan juga menjadi pusat pelestarian tradisi dan budaya Tionghoa di Kota Padang. </p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p>\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Berbagai kegiatan seperti pertemuan keluarga besar marga Tan, penghormatan kepada leluhur, kegiatan sosial, serta perayaan hari besar masyarakat Tionghoa seperti Tahun Baru Imlek dan kegiatan budaya lainnya masih menjadi bagian dari aktivitas organisasi. Tradisi tersebut menjadi sarana untuk menjaga hubungan kekerabatan, mempertahankan identitas budaya, serta memperkuat keberadaan komunitas Tionghoa dalam sejarah perkembangan Kota Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Himpunan Keluarga Tan (Eng Tjoan Tong) memiliki karakter arsitektur yang memperlihatkan perpaduan antara gaya Eropa dan Tionghoa (China). Pengaruh Eropa terlihat pada bentuk fisik dan struktur arsitektural bangunan, seperti tata ruang, fasad, serta elemen konstruksi yang mencerminkan bangunan kolonial. Sementara itu, unsur Tionghoa tampak pada tampilan bagian muka bangunan melalui penggunaan warna khas berupa merah menyala dan kuning pada pintu, jendela, serta lis dinding bagian atas. Pada bagian lantai atas terdapat teras atau serambi depan yang dibatasi oleh dinding pagar jeruji kayu sebagai salah satu ciri khas bangunan lama. Seiring perkembangan waktu, bangunan ini telah mengalami renovasi yang menyebabkan beberapa perubahan, baik pada bagian eksterior maupun interior bangunan. Meskipun demikian, Gedung Himpunan Keluarga Tan masih mempertahankan nilai sejarahnya sebagai salah satu bangunan peninggalan komunitas Tionghoa di kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.362032999999883,-0.962361]}},{"type":"Feature","properties":{"fid":"13","Kategori":"Cagar Budaya 13","Nama_Awal":"Hok Teng Tong","Masa trans":"Himpunan Tjinta Teman","bangunan s":"Himpunan Tjinta Teman","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"36","no iventra":"44/BCB-TB/A/01/2007","tahun ber":"1863","kepemilika":"Himpunan Tjinta Teman (HTT)","pengelolaa":"Himpunan Tjinta Teman (HTT)","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_htt.JPG","foto plaka":"Tidak ditemukan plakat saat di lapangan","Foto Tradi":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_Perayaan HTT.png","Alamat":"Jl.  Kelenteng II No.331","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'43.11\"BT", "Lintang": "0°57'44.95\"LS","Longitude_":100.36198,"Langitude_":-0.96249,"Fungsi Bangunan":"Gedung organisasi sosial, budaya, dan perkumpulan masyarakat Tionghoa","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Himpunan Tjinta Teman (HTT) atau Hok Tek Tong merupakan organisasi sosial budaya masyarakat Tionghoa di Kota Padang yang berdiri sejak 23 Agustus 1863. Organisasi ini awalnya berfungsi sebagai wadah perlindungan dan solidaritas bagi para pedagang serta perantau Tionghoa, kemudian berkembang menjadi pusat kegiatan sosial, budaya, dan pelestarian tradisi masyarakat Tionghoa. Gedung HTT menjadi salah satu bangunan bersejarah di kawasan Kota Tua Padang yang masih aktif digunakan untuk kegiatan organisasi, perayaan Imlek, Cap Go Meh, kegiatan sembahyang leluhur, serta berbagai aktivitas sosial kemasyarakatan. Himpunan Tjinta Teman (HTT) juga membuat festival untuk acara besar.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Hok Tek Tong (Himpunan Tjinta Teman/HTT) merupakan bangunan bersejarah yang berdiri sejak tahun 1863 dan berfungsi sebagai pusat kegiatan sosial, budaya, dan keagamaan masyarakat Tionghoa di Kota Padang. Bangunan ini terdiri dari dua lantai dengan perpaduan arsitektur Tionghoa dan kolonial yang terlihat pada fasad, ornamen dekoratif, serta penggunaan warna khas merah, putih, dan emas. Ciri khas bangunan tampak pada ornamen medalion (roundel) bermotif Tionghoa balkon memanjang, ornamen kaligrafi Tionghoa, jendela berbentuk lingkaran, serta patung singa penjaga pada pintu masuk. Meskipun telah mengalami perubahan berupa pelebaran bangunan, karakter arsitektur aslinya tetap dipertahankan. Hingga saat ini, Gedung HTT masih digunakan sebagai pusat kegiatan sosial budaya masyarakat Tionghoa dan menjadi salah satu bangunan cagar budaya di kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.361974999999887,-0.962486]}},{"type":"Feature","properties":{"fid":"14","Kategori":"Cagar Budaya 14","Nama_Awal":"Rumah Tinggal Ang Sia","Masa trans":"Rumah Tinggal","bangunan s":"Rumah Tinggal Ang Sia","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"33","no iventra":"42/BCB-TB/A/01/2007","tahun ber":"Awal Abad ke-1900","kepemilika":"Milik Pribadi","pengelolaa":"Pemilik Rumah","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_Rumah Tinggal Ang Sia.png","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Rumah Tinggal Ang Sia.jpeg","Foto Tradi":null,"Alamat":"Jl.  Kelenteng No.96","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat ","Bujur":"100°21'43.72\"BT", "Lintang": "0°57'44.98\"LS","Longitude_":100.36214,"Langitude_":-0.96249,"Fungsi Bangunan":"Rumah Tinggal ( Tidak dihuni)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Rumah Tinggal Ang Sia merupakan salah satu bangunan cagar budaya di Kawasan Kota Tua Padang yang berlokasi di Jalan Kelenteng No. 268, Kelurahan Kampung Pondok, Kecamatan Padang Barat, Kota Padang. Bangunan ini pada awalnya didirikan sekitar tahun 1876 sebagai kediaman keluarga Ang Sia, salah satu klan Tionghoa yang bermukim dan berperan dalam perkembangan kawasan perdagangan Kampung Pondok. Pada tahun 1921, bangunan ini tercatat sebagai kediaman Klan Ang Xia dan saat ini dimiliki oleh Wiriko Angkriawan. Lingkungan di sekitarnya didominasi oleh bangunan perkantoran, gudang, serta rumah tinggal yang mencerminkan karakter kawasan niaga bersejarah. Sebagai salah satu peninggalan permukiman masyarakat Tionghoa di Kota Padang, bangunan ini memiliki nilai sejarah yang erat kaitannya dengan perkembangan aktivitas perdagangan dan kehidupan sosial di kawasan Kota Tua. Rumah Tinggal Ang Sia telah ditetapkan sebagai Bangunan Cagar Budaya dengan Nomor Inventaris 42/BCB-TB/A/01/2020 karena memiliki nilai penting dari aspek sejarah, budaya, dan arsitektur, serta masih mempertahankan karakter bangunan yang menjadi bagian dari identitas kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Rumah Tinggal Ang Sia merupakan bangunan berlantai dua yang masih mempertahankan karakter arsitektur aslinya. Ciri khas bangunan ini terletak pada lantai dua yang memiliki beranda memanjang dengan pagar pembatas, sedangkan bagian lantai bawah ditopang oleh pilar-pilar beton bergaya Doria. Fasad bangunan didominasi warna hijau dengan kombinasi putih pada dinding bagian bawah dan pilar, sementara dinding lantai atas serta tiang-tiang kayunya dicat berwarna hijau sehingga memberikan tampilan yang khas. Pada bagian depan bangunan telah ditambahkan area perluasan yang dilengkapi pagar pelindung. Meskipun masih berdiri dengan bentuk utama yang relatif utuh, bangunan ini saat ini tidak lagi dihuni. Kondisi tersebut menjadikan Rumah Tinggal Ang Sia lebih berfungsi sebagai bangunan bersejarah yang merepresentasikan arsitektur permukiman masyarakat Tionghoa di Kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.362143999999887,-0.962494]}},{"type":"Feature","properties":{"fid":"15","Kategori":"Cagar Budaya 15","Nama_Awal":"Rumah Tinggal Neo Seng Jaue","Masa trans":"Rumah Tinggal Andreas CH","bangunan s":"Footy Indoor Soccer","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"37","no iventra":"45/BCB-TB/A/01/2007","tahun ber":"Akhir Abad ke-19","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Rumah Tinggal Andreas CH.jpeg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Rumah Tinggal Andreas CH.jpg","Foto Tradi":null,"Alamat":"Jl. Kelenteng No.335-336","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'42.24\"T", "Lintang": "0°57'45.40\"LS","Longitude_":100.36173,"Langitude_":-0.96261,"Fungsi Bangunan":"Kantor Lapangan Futsal","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Rumah Tinggal Andreas CH merupakan salah satu bangunan bersejarah di Kawasan Kota Tua Padang yang pada awalnya berfungsi sebagai rumah tinggal. Seiring perkembangan kawasan, bangunan ini mengalami perubahan fungsi dan pernah dimanfaatkan untuk Footy Indoor Soccer. Saat ini, bangunan tersebut digunakan sebagai kantor pengelola lapangan futsal, sehingga tetap berfungsi secara aktif tanpa menghilangkan keberadaannya sebagai bagian dari kawasan bersejarah Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini terdiri atas dua lantai. Pada lantai bawah terdapat teras di bagian depan yang ditopang oleh dua tiang berbentuk silindris. Pintu dan jendela pada lantai bawah menggunakan warna cokelat muda. Sementara itu, lantai atas pada bentuk awalnya tidak memiliki teras di bagian depan. Fasad lantai atas berupa deretan jendela kaca yang menjorok ke arah depan bangunan. Pada bagian bawah deretan jendela tersebut terdapat elemen dinding berupa jeruji kayu yang menjadi salah satu karakter arsitektur bangunan.</p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p>\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Saat ini, bangunan telah mengalami perubahan, terutama pada bagian lantai atas. Perubahan terlihat pada bagian depan bangunan yang telah ditambahkan teras atau balkon sehingga mengubah bentuk fasad aslinya. Perubahan juga terjadi pada fungsi bangunan. Bangunan yang pada awalnya digunakan sebagai rumah tinggal kini telah beralih fungsi menjadi fasilitas olahraga futsal. Meskipun mengalami perubahan bentuk dan fungsi, beberapa elemen arsitektur bangunan masih dapat dikenali.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.361732999999887,-0.962611]}},{"type":"Feature","properties":{"fid":"16","Kategori":"Cagar Budaya 16","Nama_Awal":"-","Masa trans":"PT. Buana Andalas ","bangunan s":"PT. Buana Andalas ","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"34","no iventra":"34/BCB-TB/A/01/2007","tahun ber":"1895","kepemilika":"PT. Buana Andalas","pengelolaa":"PT. Buana Andalas","kondisi fi":"Rusak Parah","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_PT. Buana Andalas.jpeg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Pelakat Pt Buana Andalas.jpeg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.20","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'46.67\"BT", "Lintang": "0°57'46.17\"LS","Longitude_":100.36296,"Langitude_":-0.96282,"Fungsi Bangunan":"Bangunan Kosong","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Berdasarkan hasil survei lapangan dan penelusuran literatur, belum ditemukan informasi yang memadai mengenai sejarah bangunan ini, termasuk tahun pembangunan dan fungsi awalnya. Saat ini, bangunan dalam kondisi kosong dan sudah tidak digunakan selama kurang lebih 12 tahun. Kondisi tersebut menyebabkan bangunan tidak mendapatkan pemanfaatan dan pemeliharaan secara optimal.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Secara keseluruhan, bangunan ini menunjukkan karakter arsitektur kolonial yang merupakan perpaduan antara unsur arsitektur Tionghoa dan kolonial. Unsur arsitektur Tionghoa terlihat pada penggunaan pintu kayu berwarna merah yang terdiri atas dua daun pintu berbentuk persegi panjang dan berukuran relatif lebar. Karakter Tionghoa juga diperkuat dengan keberadaan elemen Tou-Kung sebagai salah satu unsur konstruksi dan dekoratif khas arsitektur Tionghoa. Sementara itu, karakter kolonial terlihat pada penggunaan dinding yang relatif tebal, sekitar 30 cm, bentuk bangunan yang tinggi, serta pola diagonal pada daun pintu. Bangunan terdiri atas dua lantai. Pada lantai dasar terdapat balkon terbuka, sedangkan lantai atas tidak memiliki balkon. Bagian lantai atas sedikit menjorok ke arah depan dibandingkan lantai dasar sehingga membentuk bagian yang menaungi balkon. Struktur pada bagian atas menggunakan material kayu. Fasad depan bangunan didominasi oleh jendela kaca dengan bingkai kayu, sementara bukaan jendela juga terdapat pada sisi timur bangunan. Secara keseluruhan, denah bangunan memanjang ke arah belakang. Pasca gempa bumi tahun 2009, beberapa bagian eksterior bangunan mengalami kerusakan, terutama pada jendela lantai atas. Selain kerusakan akibat gempa, kondisi bangunan semakin menurun karena telah kosong dan tidak digunakan selama kurang lebih 12 tahun. Minimnya pemeliharaan menyebabkan beberapa komponen bangunan mengalami kerusakan dan penurunan kondisi fisik.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.362963999999891,-0.96282]}},{"type":"Feature","properties":{"fid":"17","Kategori":"Cagar Budaya 17","Nama_Awal":"Kantor NV Internatio (1910)","Masa trans":"Kantor PT. Cipta Niaga (1976)","bangunan s":"Kantor PT. Perusahaan Dagang Indonesia","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"30","no iventra":"15/BCB-TB/A/01/2007","tahun ber":"1910","kepemilika":"PT. Perusahaan Dagang Indonesia","pengelolaa":"PT. Perusahaan Dagang Indonesia","kondisi fi":"Rusak Sedang ","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_Kantor PT. Cipta Niaga.png","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Kantor NV International.jpg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.23","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'48.12\"BT", "Lintang": "0°57'46.32\"LS","Longitude_":100.36337,"Langitude_":-0.96287,"Fungsi Bangunan":"Bangunan Kosong","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pada awalnya, bangunan ini merupakan milik NV Internatio, yaitu perusahaan dagang Belanda yang beroperasi di Kota Padang. Gedung NV Internatio diperkirakan dibangun sekitar tahun 1910 dan menjadi bagian dari perkembangan aktivitas perdagangan pada masa kolonial. Setelah tahun 1950-an, bangunan tersebut diambil alih dan digunakan oleh PT Cipta Niaga. Seiring dengan pembubaran PT Cipta Niaga pada sekitar tahun 2000-an, pengelolaan dan kepemilikan bangunan kemudian beralih kepada PT Perusahaan Perdagangan Indonesia (PPI). Dengan demikian, bangunan ini memiliki keterkaitan sejarah dengan perkembangan kegiatan perdagangan sejak masa kolonial hingga periode pascakemerdekaan.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan yang saat ini dimiliki oleh BUMN ini menampilkan karakter arsitektur neoklasik yang berkembang sebelum tahun 1920. Secara umum, bangunan masih memperlihatkan karakter dan gaya arsitektur aslinya. Bangunan terdiri atas dua lantai dengan penggunaan material lantai berupa ubin atau cor pada bagian tertentu dan material kayu pada bagian pintu depan. Fasad bagian depan memiliki komposisi yang simetris dengan tiga bagian bukaan utama. Pada lantai atas terdapat tiga jendela. Bagian fasad di atas pintu dan jendela dibuat lebih tinggi dan diakhiri dengan bentuk lengkung serta ornamen menyerupai segitiga lancip. Komposisi tersebut memperlihatkan karakter arsitektur kolonial yang kuat. Pasca gempa bumi 30 September 2009, bangunan mengalami kerusakan berat dengan tingkat kerusakan diperkirakan mencapai sekitar 90%. Kerusakan meliputi bagian atap, dinding, lantai, serta lantai dua yang mengalami kerusakan cukup parah. Saat ini, bangunan dalam kondisi kosong dan tidak difungsikan. Kondisi tersebut menyebabkan bangunan perlu mendapatkan perhatian dan pemeliharaan agar kerusakan tidak semakin parah serta karakter arsitektur dan nilai sejarahnya tetap dapat dipertahankan.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.363366999999883,-0.962867]}},{"type":"Feature","properties":{"fid":"18","Kategori":"Cagar Budaya 18","Nama_Awal":"Gedung Hong Jang Hoo","Masa trans":"Gedung Hong Jang Hoo","bangunan s":"Gedung Hong Jang Hoo","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"35","no iventra":"14/BCB-TB/A/01/2007","tahun ber":"1921","kepemilika":"Swasta","pengelolaa":"Swasta","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Gedung Hong Jang Hoo.jpg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Gedung Hong Jang Hoo.jpg","Foto Tradi":null,"Alamat":"Jl.  Batang Arau No.14","kelurahan":"Batang Arau","kecamatan":"Padang Selatan ","Bujur":"100°21'47.65\"BT", "Lintang": "0°57'45.72\"LS","Longitude_":100.36324,"Langitude_":-0.9627,"Fungsi Bangunan":"Bangunan komersial (ruko/perdagangan)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Kawasan Batang Arau masih menyimpan jejak sejarah melalui deretan bangunan cagar budaya dan bangunan tua yang menjadi saksi perkembangan Kota Padang pada masa kolonial. Salah satu di antaranya adalah Gedung Hong Jang Hoo yang berdiri di Jalan Batang Arau No. 14, Kelurahan Batang Arau, Kecamatan Padang Selatan, Kota Padang. Bangunan yang tampak seolah terdiri atas dua massa bangunan kembar ini dibangun pada tahun 1921 dan tercatat sebagai objek cagar budaya dengan Nomor Inventaris 14/BCB-TB/A/01/2007. Pada awal pembangunannya, gedung ini berfungsi sebagai kantor perusahaan dagang Hong Jang Hoo yang berperan dalam aktivitas perdagangan di kawasan pelabuhan Batang Arau.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Hong Jang Hoo merupakan bangunan cagar budaya dua lantai yang dibangun pada tahun 1921 dengan mengusung arsitektur kolonial bergaya Neoklasik. Ciri khas bangunan ini sebelumnya tampak pada fasad depan yang simetris dengan pedimen berbentuk segitiga di bagian atas, disertai tulisan nama gedung dan tahun pembangunannya sebagai penanda identitas bangunan. Arsitektur tersebut mencerminkan karakter bangunan perdagangan kolonial yang berkembang di kawasan Batang Arau pada awal abad ke-20. Gempa bumi Sumatera Barat pada 30 September 2009 menyebabkan bangunan ini mengalami kerusakan yang cukup signifikan, diperkirakan mencapai sekitar 40%. Setelah peristiwa tersebut, bangunan direnovasi dengan mengadopsi arsitektur modern minimalis sehingga sebagian besar elemen fasad asli, termasuk tulisan nama gedung pada bagian atas bangunan, tidak lagi dipertahankan. Perubahan tersebut mengurangi tingkat keaslian arsitektur yang sebelumnya menjadi salah satu nilai penting bangunan cagar budaya. Saat ini Gedung Hong Jang Hoo diketahui masih dimanfaatkan sebagai gudang atau tempat penyimpanan barang. Aktivitas di sekitar bangunan relatif minim karena gedung lebih sering dalam keadaan tertutup, sehingga fungsi pemanfaatannya tidak terlihat secara jelas dari luar.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.363235999999887,-0.9627]}},{"type":"Feature","properties":{"fid":"19","Kategori":"Cagar Budaya 19","Nama_Awal":"Stasiun KA Pulai Air","Masa trans":"Stasiun KA Pulai Air","bangunan s":"Stasiun KA Pulai Air","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"65","no iventra":"69/BCB-TB/A/01/2007","tahun ber":"1887","kepemilika":"PT KAI Regional 2 Sumatera Barat","pengelolaa":"PT KAI Regional 2 Sumatera Barat","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_stasiun pulau air.png","foto plaka":"Tidak dijumpai di lokasi","Foto Tradi":null,"Alamat":"Jl.  Pulau Air No.40","kelurahan":"Pasar Gadang","kecamatan":"Padang Selatan","Bujur":"100°21'57.86\"BT", "Lintang": "0°57'38.04\"LS","Longitude_":100.36607,"Langitude_":-0.96057,"Fungsi Bangunan":"Stasiun KA Pulau Air","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pembangunan stasiun ini tidak dapat dipisahkan dari penemuan batu bara di wilayah Sumatera Barat dan perkembangan jaringan transportasi kereta api pada masa kolonial. Pembangunan jalur kereta api dilakukan untuk menghubungkan daerah penghasil batu bara dengan kawasan pelabuhan di Kota Padang. Stasiun ini dibangun pada tahun 1887 dan menjadi salah satu bagian penting dalam perkembangan awal perkeretaapian di Sumatera.</p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p>\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pada masa awal operasionalnya, jalur kereta api memiliki fungsi utama untuk mengangkut batu bara dari Sawahlunto menuju Pelabuhan Emmahaven (Teluk Bayur) di Kota Padang. Keberadaan jalur tersebut mendukung kegiatan perdagangan dan distribusi komoditas pertambangan dari pedalaman Sumatera Barat menuju kawasan pesisir. Dalam perkembangannya, kawasan stasiun menjadi bagian dari jaringan transportasi dan perdagangan penting di Kota Padang. Keberadaan stasiun beserta jaringan relnya tidak hanya berperan dalam pengangkutan batu bara, tetapi juga menjadi bagian dari perkembangan ekonomi dan infrastruktur transportasi Kota Padang pada masa kolonial.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Stasiun Pulau Aie merupakan salah satu bangunan bersejarah yang berada pada jalur kereta api Simpang Haru–Muaro Padang. Pada masa perkembangannya, kawasan stasiun memiliki fungsi sebagai tempat pemberhentian penumpang sebelum menuju kawasan Muaro Padang. Saat ini, bangunan Stasiun Pulau Aie telah mengalami renovasi dan dimanfaatkan sebagai terminal atau tempat pemberhentian penumpang menuju Bandara Internasional Minangkabau (BIM).</p>\n<p style=\"-qt-paragraph-type:empty;margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\"><br /></p>\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pintu utama bangunan terletak di bagian tengah fasad. Meskipun telah mengalami renovasi dan perubahan fungsi, sebagian besar material asli bangunan masih dipertahankan, termasuk bagian lantai dan beberapa elemen ornamen arsitekturnya. Namun, terdapat pula beberapa penambahan elemen dan perubahan pada bangunan yang disesuaikan dengan kebutuhan fungsi saat ini sebagai fasilitas pelayanan transportasi. Secara keseluruhan, Stasiun Pulau Aie masih memperlihatkan karakter bangunan lama dan memiliki nilai sejarah sebagai bagian dari perkembangan jaringan transportasi kereta api di Kota Padang. Keberadaan material asli yang masih dipertahankan menjadi salah satu unsur penting dalam menjaga karakter bangunan, meskipun telah mengalami adaptasi terhadap fungsi modern.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.366071999999889,-0.960567]}},{"type":"Feature","properties":{"fid":"20","Kategori":"Cagar Budaya 20","Nama_Awal":"Hotel Pasar Gadang","Masa trans":"Gedung Juang BPPI","bangunan s":"Gedung Juang BPPI","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"45","no iventra":"07/BCB-TB/A/01/2007","tahun ber":"1987","kepemilika":"Pemerintah Kota Padang","pengelolaa":"Pemerintah Kota Padang BPCB Sumatera Barat","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Gedung Juang BPPI.jpg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Gedung Juang BPPI.jpg","Foto Tradi":null,"Alamat":"Jl.  Pasar Mudik No.54","kelurahan":"Pasar Gadang","kecamatan":"Padang Selatan","Bujur":"100°22'06.27\"BT", "Lintang": "0°57'32.72\"LS","Longitude_":100.36841,"Langitude_":-0.95909,"Fungsi Bangunan":"Museum Kota Padang dan Kantor DC 45 Kota Padang","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini awalnya merupakan Hotel Pasar Gadang yang pada masa perjuangan kemerdekaan digunakan sebagai markas Barisan Perjuangan Pemuda Indonesia (BPPI) Kota Padang. Bangunan ini memiliki nilai sejarah yang berkaitan dengan perjuangan pemuda di Kota Padang. Saat ini, bangunan tersebut berfungsi sebagai Museum BPPI dan DHD 45 Cabang Padang yang menyimpan berbagai peninggalan sejarah perjuangan kemerdekaan.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung Juang 45 BPPI merupakan bangunan cagar budaya yang terdiri atas dua lantai dengan karakter arsitektur kolonial yang masih terlihat pada bagian fasad depan. Bagian depan bangunan tetap mempertahankan bentuk aslinya sejak masa kolonial, sedangkan bagian interior telah mengalami beberapa perubahan dan penyesuaian. Dampak gempa bumi 30 September 2009 menyebabkan munculnya retakan pada beberapa bagian bangunan sehingga diperlukan proses renovasi. Bangunan memiliki halaman kosong di bagian belakang. Pada lantai pertama terdapat ruang-ruang kantor, perpustakaan, serta pajangan foto-foto bersejarah yang ditempatkan di dekat pintu masuk. Sementara itu, lantai kedua berupa ruang terbuka yang saat ini belum dimanfaatkan secara optimal. Renovasi yang telah dilakukan bertujuan mempertahankan nilai historis bangunan sekaligus menyesuaikannya dengan fungsi baru sebagai pusat pengelolaan Kawasan Kota Tua Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.368407999999889,-0.959089]}},{"type":"Feature","properties":{"fid":"21","Kategori":"Cagar Budaya 21","Nama_Awal":"Penginapan Nagara","Masa trans":"Hotel Nagara","bangunan s":"Masih dalam proses renovasi","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"44","no iventra":"51/BCB-TB/A/01/2007","tahun ber":"1918","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Masih dalam Masa Renovasi","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_gambar hotel nagara.png","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Hotel Nagara.jpeg","Foto Tradi":null,"Alamat":"Jl.  Pasar Mudik No.22-24","kelurahan":"Pasar Gadang","kecamatan":"Padang Selatan","Bujur":"100°22'03.85\"BT", "Lintang": "0°57'32.77\"LS","Longitude_":100.36774,"Langitude_":-0.9591,"Fungsi Bangunan":"Masih renovasi","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Penginapan Nagara merupakan bangunan bersejarah di Kawasan Kota Tua Padang yang pada masa kolonial berfungsi sebagai penginapan bagi pedagang, pelaut, dan pendatang di sekitar Pelabuhan Muaro. Bangunan ini mencerminkan perkembangan aktivitas perdagangan dan pelabuhan Kota Padang. Setelah mengalami kerusakan akibat gempa 30 September 2009, bangunan tidak lagi digunakan sebagai penginapan dan saat ini masih dalam proses renovasi sebagai bagian dari upaya pelestarian cagar budaya.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Penginapan Nagara merupakan bangunan cagar budaya yang terdiri atas dua massa bangunan yang menyatu. Fasadnya memiliki pilar persegi, lengkungan dekoratif, deretan jendela kaca, serta teras pada kedua sudut yang mencerminkan karakter arsitektur kolonial. Bangunan telah mengalami beberapa renovasi dan perubahan elemen, terutama pada jendela, pintu utama, serta penambahan pagar. Saat ini masih dalam proses renovasi, namun karakter arsitektur kolonial pada fasad tetap terlihat dan menjadi bagian penting dari nilai historis bangunan.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.36773599999988,-0.959103]}},{"type":"Feature","properties":{"fid":"22","Kategori":"Cagar Budaya 22","Nama_Awal":"Rumah Tinggal","Masa trans":"Rumah Tinggl / Penginapan","bangunan s":"Gudang Rempah-rempah ( Rumah Tinggal Sidin)","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"43","no iventra":"50/BCB-TB/A/01/2007","tahun ber":"1910","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Rumah Tinggal Sidin.jpg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Rumah Tinggal Sidin.jpg","Foto Tradi":null,"Alamat":"Jl.  Pasar Hilir No.70","kelurahan":"Pasar Gadang","kecamatan":"Pasar Gadang","Bujur":"100°22'0.76\"BT", "Lintang": "0°57'32.92\"S","Longitude_":100.36688,"Langitude_":-0.95914,"Fungsi Bangunan":"Gudang Rempah-rempah","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini didirikan pada tahun 1910 dan awalnya digunakan sebagai tempat usaha keluarga Sidin Lengkang Sutun untuk menjual topi. Pada tahun 1948, bangunan beralih fungsi menjadi hotel, kemudian sejak sekitar tahun 1970 hingga sekarang digunakan sebagai gudang penyimpanan rempah-rempah. Perubahan fungsi tersebut mencerminkan perkembangan aktivitas perdagangan di Kawasan Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini terdiri atas dua lantai dengan karakter arsitektur kolonial, ditandai oleh atap pelana, kolom persegi, lengkungan pada bukaan, serta balkon memanjang di lantai dua. Struktur bangunan menggunakan pasangan batu bata dengan dinding yang cukup tebal, sementara fasad didominasi warna kuning dan hijau. Bagian dalam masih berupa ruang luas yang digunakan sebagai gudang rempah-rempah, sedangkan lantai dua terdiri atas ruang besar dan dua kamar. </p>\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gempa bumi 30 September 2009 menyebabkan kerusakan sedang, seperti runtuhnya sebagian plafon dan retakan pada dinding. Hingga saat ini bangunan masih digunakan sebagai gudang, tetapi kondisinya cukup memprihatinkan karena belum memperoleh penanganan konservasi secara menyeluruh.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.366877999999886,-0.959144]}},{"type":"Feature","properties":{"fid":"23","Kategori":"Cagar Budaya 23","Nama_Awal":"Toko Grosir","Masa trans":"Gudang / Distributor Semen","bangunan s":"Gudang / Distributor Semen","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"42","no iventra":"49/BCB-TB/A/01/2007","tahun ber":"1913","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_gudang semen.jpg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat gudang semen.jpg","Foto Tradi":null,"Alamat":"Jl.  Pasar Mudik No.4","kelurahan":"Pasar Gadang","kecamatan":"Padang Selatan","Bujur":"100°21'57.02\"BT", "Lintang": "0°57'34.00\"LS","Longitude_":100.36584,"Langitude_":-0.95944,"Fungsi Bangunan":"Gudang Semen","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Gedung distributor semen merupakan salah satu bangunan yang tercantum dalam daftar Cagar Budaya Kota Padang berdasarkan salinan Peraturan Wali Kota tahun 1998. Bangunan ini berada di Jalan Pasar Hilir Nomor 28, Pasa Gadang, dan pada bagian puncak fasad terdapat tulisan tahun 1913 yang menjadi salah satu penanda usia bangunan. Sekitar tahun 2017, bangunan ini pernah mengalami perubahan fisik yang cukup signifikan. Sebagian bangunan sempat dibongkar atau dipotong, sementara bagian lainnya direnovasi dengan rencana perubahan bentuk. Namun, karena bangunan tersebut merupakan bagian dari cagar budaya, bentuknya kemudian dikembalikan dan disesuaikan dengan karakter bangunan sebelumnya.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini memiliki tampilan fasad yang kokoh dan kuat, yang diperkuat oleh keberadaan pilar-pilar berbentuk persegi pada bagian depan lantai bawah. Di antara pilar-pilar tersebut terdapat bukaan berbentuk lengkung pada bagian atas yang menjadi salah satu karakter utama fasad bangunan. Pada lantai dua, jendela bagian depan juga memiliki bentuk lengkung pada bagian atas. Dinding bagian depan dibuat menjulang hingga menutupi bagian atas fasad. Pada bagian tengah terdapat bidang berbentuk lengkung yang diapit oleh dua elemen dekoratif menyerupai salib, sedangkan pada kedua sudut kiri dan kanan terdapat kubah semu berbentuk bulat. Secara keseluruhan, bentuk dasar dan karakter arsitektur bangunan masih relatif dipertahankan. Perubahan terutama terlihat pada bagian jendela yang telah diganti menggunakan jendela kaca nako, sehingga terdapat perbedaan antara elemen asli dan elemen yang telah diperbarui. Bangunan ini terdiri atas dua petak bangunan. Salah satu petak telah mengalami renovasi oleh pemilik. Meskipun demikian, renovasi tersebut masih mempertahankan gaya arsitektur yang menyerupai bentuk bangunan aslinya. Dengan demikian, karakter visual dan elemen utama fasad bangunan masih dapat dikenali meskipun telah mengalami beberapa perubahan.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.36583899999988,-0.959444]}},{"type":"Feature","properties":{"fid":"24","Kategori":"Cagar Budaya 24","Nama_Awal":"Toko Kain / Firma Banda","Masa trans":"Rumah Tinggal Keluarga Abson","bangunan s":"Komesial (Cucian mobil dan motor DH)","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"41","no iventra":"48/BCB-TB/A/01/2007","tahun ber":"1910","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Rumah Tinggal Keluarga Abson1.jpg","foto plaka":"C:\\Users\\win10\\Downloads\\FILE SKRIPSI RAHMA\\qgis2web_2026_09_07-00_30_23_411118\\images\\C__Users_win10_Downloads_JURNAL_New folder_Plakat Rumah Tinggal Keluarga Abson.jpg","Foto Tradi":null,"Alamat":"Jl. Pasar Hilir No 74","kelurahan":"Pasar Gadang","kecamatan":"Padang Selatan","Bujur":"100°21'55.76\"T", "Lintang": "0°57'34.83\"S","Longitude_":100.36549,"Langitude_":-0.95968,"Fungsi Bangunan":"Tempat tunggu cuci mobil dan motor","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini didirikan sekitar tahun 1910 dan pada awalnya difungsikan sebagai toko kain atau firma dagang Banda yang melayani aktivitas perdagangan di kawasan Kota Tua Padang. Keberadaan bangunan ini mencerminkan berkembangnya kegiatan ekonomi dan perdagangan pada masa kolonial, khususnya dalam sektor distribusi tekstil. Seiring perubahan fungsi kawasan dan kebutuhan masyarakat, bangunan tersebut tidak lagi digunakan sebagai toko kain. Saat ini bangunan dimanfaatkan sebagai tempat usaha cuci mobil dan sepeda motor, sekaligus difungsikan sebagai ruang tunggu bagi pelanggan. Meskipun telah mengalami perubahan fungsi, bangunan ini masih menjadi bagian dari jejak sejarah perkembangan kawasan perdagangan di Kota Tua Padang.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan ini pada awalnya merupakan rumah tinggal sekaligus toko kain milik keluarga Abson. Bangunan berbentuk deretan (row building) yang terbagi menjadi 11 kavling, dengan setiap kavling ditempati oleh satu keluarga yang berbeda. Pola bangunan seperti ini merupakan karakter kawasan perdagangan dan permukiman di Kota Tua Padang, di mana fungsi hunian dan aktivitas usaha berada dalam satu bangunan. Lantai dasar dimanfaatkan sebagai teras depan dan area kegiatan usaha, sedangkan lantai atas berfungsi sebagai ruang hunian dengan bagian depan didominasi oleh bukaan jendela kaca. Seiring berjalannya waktu, sebagian besar unit bangunan telah mengalami perubahan bentuk dan penyesuaian arsitektur sesuai dengan kebutuhan masing-masing pemilik atau penghuni. Perubahan yang paling mencolok terjadi pada bangunan di bagian sudut, yang sebelumnya memiliki bentuk arsitektur khas dan menjadi salah satu elemen penanda deretan bangunan tersebut. Bangunan sudut tersebut telah dibongkar dan digantikan dengan bangunan baru yang kini digunakan sebagai tempat usaha cuci mobil. Bangunan baru tersebut memiliki gaya arsitektur yang berbeda dengan bangunan-bangunan di sekitarnya, sehingga mengurangi kesatuan visual dan karakter historis deretan bangunan yang sebelumnya masih dapat dikenali sebagai bangunan baris berarsitektur kolonial.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.365488999999883,-0.959675]}},{"type":"Feature","properties":{"fid":"25","Kategori":"Cagar  Budaya 25","Nama_Awal":"Toko Batik","Masa trans":"Rumah Tinggal Kel. M. Yatim","bangunan s":"Rumah Tinggal Kel. M. Yatim","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"39","no iventra":"46/BCB-TB/A/01/2007","tahun ber":"1902","kepemilika":"Keluarga M. Yatim ","pengelolaa":"Keluarga M. Yatim ","kondisi fi":"Hancur Total ","dokumentas":"C:\\Users\\win10\\Pictures\\Screenshots\\kel M. Yatim.png","foto plaka":"Tidak ditemukan di lapangan","Foto Tradi":null,"Alamat":"Jl. Pasar Malintang No.2-10","kelurahan":"Pasa Gadang","kecamatan":"Padang Selatan","Bujur":"100°21′53.90″ BT","Lintang":"0°57′33.40″ LS","Longitude_":100.36497,"Langitude_":-0.95928,"Fungsi Bangunan":"Rumah Tinggal (Sudah Musnah)","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Bangunan cagar budaya ini didirikan pada tahun 1902 dan awalnya beroperasi sebagai toko batik di kawasan perdagangan Kota Padang di era kolonial Hindia Belanda. Bangunan kemudian dimiliki oleh pihak swasta atau individu, dan sekarang digunakan sebagai tempat tinggal keluarga M. Yatim. Dalam upaya untuk menjaga warisan seni kolonial Sumatera Barat, bangunan ini telah ditetapkan sebagai cagar budaya dengan Nomor Inventaris 46/BCB-TB/A/01/2007. Namun, data terbaru menunjukkan bahwa struktur bersejarah ini telah hancur atau tidak ada lagi di lokasi karena perubahan kota dan kerusakan struktural.</p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Sebelum musnah, objek cagar budaya ini merupakan bangunan berarsitektur kolonial abad ke-20 awal (tahun 1902) dengan tipologi menyerupai rumah toko (shophouse) kuno. Bangunan ini terletak di kawasan bersejarah Jl. Pasar Malintang No. 2-10, Kelurahan Ranah Parak Rumbio, Kecamatan Padang Selatan, Kota Padang. Struktur aslinya memiliki karakteristik khas bangunan niaga-hunian era kolonial, yang mencerminkan sisa-sisa perkembangan aktivitas perdagangan masyarakat di sekitar area pelabuhan lama Muaro Padang.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.365127221048681,-0.959207759836538]}},{"type":"Feature","properties":{"fid":"26","Kategori":"Cagar Budaya 26","Nama_Awal":"Toko Batik","Masa trans":"Rumah Tinggal Kel. H. St. Zainun","bangunan s":"D\"ColonialKaffe", "statuscag": "BangunanCagarBudayaKotaPadang", "nocb": "40", "noiventra": "47/BCB-TB/A/01/2007", "tahunber": "1918", "kepemilika": "Pribadi", "pengelolaa": "Pribadi", "kondisifi": "Baik", "dokumentas": "C:\\Users\\win10\\Pictures\\Screenshots\\DColonialKaffe.png", "fotoplaka": "Tidakditemukanplakatdilapangan", "FotoTradi": null, "Alamat": "Jl.PasarMalintangNo.20", "kelurahan": "PasaGadang", "kecamatan": "PadangSelatan", "Bujur": "100°21′53.30″BT", "Lintang": "0°57′32.30″LS", "Longitude_": 100.36481, "Langitude_": -0.95897, "FungsiBangunan": "Cafe", "Sejarah": "<!DOCTYPEHTMLPUBLIC\"-//W3C//DTD HTML 4.0//EN\"\"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><metaname=\"qrichtext\"content=\"1\"/><styletype=\"text/css\">\np,li{white-space:pre-wrap;}\n</style></head><bodystyle=\" font-family:'MS Shell Dlg 2'; font-size:8.25pt; font-weight:400; font-style:normal;\">\n<pstyle=\" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;\">BangunancagarbudayainididirikandiKotaPadangpadatahun1918selamaerakolonialHindiaBelanda.Gedunginiawalnyadigunakansebagaitokobatik.Setelahitu,kepemilikandanfungsibangunanberubahmenjadiRumahTinggalKeluargaH.St.Zainun.Selanjutnya,bangunaniniditetapkansebagaiBangunanCagarBudayaresmiolehpemerintahKotaPadangdenganNomorCagarBudaya40danNomorInventaris47/BCB-TB/A/01/2007.BangunankunodengannilaisejarahtinggiinitelahdirevitalisasidandigunakankembalisebagairuangusahakomersialdengannamaD&quot;ColonialKaffe.</p></body></html>", "Deskripsi": "<!DOCTYPEHTMLPUBLIC\"-//W3C//DTD HTML 4.0//EN\"\"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><metaname=\"qrichtext\"content=\"1\"/><styletype=\"text/css\">\np,li{white-space:pre-wrap;}\n</style></head><bodystyle=\" font-family:'MS Shell Dlg 2'; font-size:8.25pt; font-weight:400; font-style:normal;\">\n<pstyle=\" margin-top:0px; margin-bottom:0px; margin-left:0px; margin-right:0px; -qt-block-indent:0; text-indent:0px;\">Objektifinidibangunpadatahun1918dengangayaarsitekturkolonial.Karakteristikfisiknyamengikutigayabangunankomersial-hunianIndia,dengandindingtebaldanlangit-langittinggisertabukaanpintudanjendelabesarkhaseraBelandauntuksirkulasiudarayangbaik.TerletakdikawasanperdaganganbersejarahKotaPadang,fasadaslibangunaninitetapdipertahankanuntukmenjagakeaslianarsitekturnya.Didalamnya,bagiandalamnyatelahdiubahuntukmendukungoperasikafemoderntanpamerusakstrukturinticagarbudaya.&quot;</p></body></html>" }, "geometry": { "type": "Point", "coordinates": [ 100.36482783106517, -0.958919118835787 ] } },{"type":"Feature","properties":{"fid":"27","Kategori":"Cagar Budaya 27","Nama_Awal":"-","Masa trans":"PT. Deli Agung Patra","bangunan s":"Padang Old Town Resto Gallery","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"26","no iventra":"36/BCB-TB/A/01/2007","tahun ber":"1910","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik ","dokumentas":"C:\\Users\\win10\\Downloads\\Kk Egi\\Padang Old Town Resto Gallery.jpeg","foto plaka":"Tidak ditemui di lapangan ","Foto Tradi":null,"Alamat":"Jl. Batang Arau No.34","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'41.86\"BT", "Lintang": "0°57'48.71\" LS","Longitude_":100.36163,"Langitude_":-0.96353,"Fungsi Bangunan":"Cafe","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Kegiatan perdagangan maritim yang terjadi di Sumatera Barat selama periode kolonial merupakan bagian integral dari pembangunan bangunan ini. Gedung ini didirikan pada tahun 1910 dan awalnya digunakan sebagai kantor administrasi dan gudang logistik perusahaan dagang Belanda yang mengekspor barang di tepi koridor Batang Arau. Pada era transisi pascakemerdekaan, bangunan ini dinasionalisasi sebagai aset negara oleh PT. Perusahaan Perdagangan Indonesia (PPI). Kemudian disewa dan dioperasikan oleh PT. Deli Agung Patra. Pada akhirnya, bangunan ini ditetapkan secara resmi sebagai Bangunan Cagar Budaya Kota Padang dengan No. Reg 26. Bangunan ini mengalami fase revitalisasi adaptif setelah gempa bumi yang terjadi pada 30 September 2009, yang menyebabkan kerusakan yang signifikan pada struktur utamanya. Kompleks bersejarah tersebut telah dihidupkan kembali dan digunakan sebagai ruang komersial-kuliner yang sekarang dikenal sebagai Padang Old Town Resto Gallery. </p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Secara arkeologis, bangunan yang dilindungi ini dibangun pada tahun 1910 dan menunjukkan campuran dari tiga budaya yang berbeda, yaitu Belanda, Tiongkok, dan Minangkabau. Pengaruh dari Eropa terlihat jelas dalam desainnya, seperti dinding bata yang tebal tanpa banyak kolom, langit-langit yang tinggi, dan beberapa pilar yang ada di bagian depan untuk pintu dan jendela besar. Gaya Tiongkok terlihat dalam bentuk rumah toko yang panjang dan menghadap ke belakang, yang terletak dekat dengan kawasan Pecinan. Di sisi lain, gaya Minangkabau ditunjukkan melalui atap yang curam dan beratap lebar agar dapat menampung banyak hujan di daerah pesisir barat Sumatera. Setelah gempa pada tahun 2009 yang merusak, bagian dinding batanya yang tua dan pilar-pilar penting yang masih ada dipelihara dengan baik. Mereka menggunakan teknologi baja yang modern dan ramah gempa, sehingga menghasilkan kombinasi desain yang menarik antara gaya industri modern dan bentuk aslinya. </p></body></html>"},"geometry":{"type":"Point","coordinates":[100.36162779999988,-0.96353084]}},{"type":"Feature","properties":{"fid":"28","Kategori":"Cagar Budaya 28","Nama_Awal":"Bersumy Wekry","Masa trans":"Kantor PT. Kerta Niaga","bangunan s":"Arau Water Park","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"23","no iventra":"37/BCB-TB/A/01/2007","tahun ber":"-","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik","dokumentas":"C:\\Users\\win10\\Downloads\\Kk Egi\\ARAU WATER PARK.jfif","foto plaka":"Tidak ditemukan di lapangan ","Foto Tradi":null,"Alamat":"Jl. Batang Arau No.46","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat","Bujur":"100°21'37.58\"BT", "Lintang": "0°57'49.33\" LS","Longitude_":100.36044,"Langitude_":-0.9637,"Fungsi Bangunan":"Kolam Berenang","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pembangunan gedung ini adalah bagian penting dari pertumbuhan perdagangan internasional dan logistik di daerah Kota Tua Padang pada zaman penjajahan Belanda. Gedung ini awalnya dibangun sebagai kantor dagang swasta bernama Bersumy Wekry dan berada di tempat strategis dekat pelabuhan Sungai Batang Arau. Setelah Indonesia merdeka, gedung ini dinasionalisasi oleh pemerintah Indonesia menjadi milik negara dan diubah fungsinya menjadi kantor PT. Kerta Niaga adalah sebuah perusahaan milik negara di bidang perdagangan. Karena pentingnya bagi sejarah kota, gedung ini diakui sebagai Bangunan Cagar Budaya Kota Padang dengan nomor 23. Meskipun gedung ini terkena dampak guncangan akibat serangkaian gempa bumi di pantai barat Sumatera, gedung ini berhasil dipertahankan melalui konservasi dan revitalisasi yang inovatif. Sekarang, gedung bersejarah ini telah sepenuhnya diubah menjadi pusat rekreasi dan komersial modern bernama Arau Water Park, yang juga membantu menghidupkan kembali ekonomi dan pariwisata di kawasan heritage Batang Arau. </p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:0px;margin-bottom:0px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Secara arkeologis, situs bersejarah dengan nomor inventaris 37/BCB-TB/A/01/2007 ini menunjukkan ciri-ciri arsitektur kolonial Eropa yang dikenal dengan gaya tropis Renaisans dari abad ke-19, yang sangat menyesuaikan dengan cuaca pantai. Ciri-ciri arsitektur kolonial yang terlihat jelas adalah dinding bata yang tebal dan kuat, langit-langit yang tinggi untuk memungkinkan udara bergerak dengan baik, serta banyak pintu dan jendela besar yang melengkung, yang biasa digunakan di bangunan pemerintahan zaman Hindia Belanda. Tata letak bangunan dirancang agar lebih panjang ke belakang sehingga ruang kantor di depan lebih efektif. Atapnya dirancang miring tajam dengan atap lebar untuk menyesuaikan dengan hujan deras yang sering terjadi di daerah tersebut. Melalui proses rekonstruksi terbaru, kondisi fisik bangunan kini dalam keadaan baik, di mana bagian luar yang bersejarah dan keaslian material lamanya tetap terjaga dengan baik, lalu dipadukan secara sempurna dengan fasilitas modern dan elemen udara tanpa menghilangkan karakter asli dari cagar budaya tersebut.</p></body></html>"},"geometry":{"type":"Point","coordinates":[100.360438899999892,-0.96370278]}},{"type":"Feature","properties":{"fid":"29","Kategori":"Cagar Budaya 29","Nama_Awal":"Bersumy Wehry","Masa trans":"Gudang PT. Kerta Niaga","bangunan s":"Arau Mini Waterpark, Cafe and Resto","status cag":"Bangunan Cagar Budaya Kota Padang","no cb":"24","no iventra":"18/BCB-TB/A/01/2007","tahun ber":"-","kepemilika":"Pribadi","pengelolaa":"Pribadi","kondisi fi":"Baik ","dokumentas":"C:\\Users\\win10\\Downloads\\Kk Egi\\Arau Mini Waterpark, Cafe and Resto.png","foto plaka":"Tidak dijumpai plakat di lapangan ","Foto Tradi":null,"Alamat":"Jl. Batang Arau No.44-48","kelurahan":"Kampung Pondok","kecamatan":"Padang Barat ","Bujur":"100°21'37.21\"BT", "Lintang": "0°57'50.24\" LS","Longitude_":100.36034,"Langitude_":-0.96396,"Fungsi Bangunan":" Cafe and Resto","Sejarah":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Pembangunan area gudang ini sangat terkait dengan jaringan bisnis pengiriman dan perkembangan perusahaan swasta di daerah Kota Tua Padang pada waktu penjajahan Belanda. Awalnya dikenal dengan nama Bersumy Wehry, bangunan ini dibuat khusus untuk menyimpan barang-barang ekspor utama sebelum dikirim dari pelabuhan Sungai Batang Arau. Setelah Indonesia merdeka, gedung ini diambil alih melalui kebijakan nasionalisasi yang mengatur aset-aset penjajah dan diubah menjadi gudang milik PT. Kerta Niaga, yang merupakan perusahaan milik negara di bidang perdagangan. Karena memiliki nilai penting dalam perkembangan sejarah ekonomi kota, tempat ini resmi diakui sebagai Bangunan Cagar Budaya di Kota Padang dengan nomor 24. Dengan menggunakan pendekatan alih fungsi yang adaptif, kompleks cagar budaya ini berhasil dipulihkan dari fungsi logistik sebelumnya menjadi ruang publik yang ramai dan komersial. Saat ini, bangunan ini berfungsi dengan baik sebagai Arau Mini Waterpark, kafe dan resto yang mendukung sektor pariwisata sejarah di Kota Padang. </p></body></html>","Deskripsi":"<!DOCTYPE HTML PUBLIC \"-//W3C//DTDHTML4.0//EN\" \"http://www.w3.org/TR/REC-html40/strict.dtd\">\n<html><head><meta name=\"qrichtext\" content=\"1\" /><style type=\"text/css\">\np, li { white-space: pre-wrap; }\n</style></head><body style=\"font-family:'MSShellDlg2';font-size:8.25pt;font-weight:400;font-style:normal;\">\n<p style=\"margin-top:12px;margin-bottom:12px;margin-left:0px;margin-right:0px;-qt-block-indent:0;text-indent:0px;\">Secara arkeologis, situs sejarah dengan nomor inventaris 18/BCB-TB/A/01/2007 ini menunjukkan jenis arsitektur bangunan gudang dari zaman kolonial di abad ke-19 yang fokus pada kekuatan bangunan dan penggunaan ruang yang efektif. Unsur arsitektur Eropa yang praktis sangat terlihat pada dinding bata yang kuat dan tebal yang tidak menggunakan kolom beton, serta langit-langit yang tinggi untuk menjaga agar barang-barang tetap kering. Denah bangunan itu dibuat seperti ruang besar untuk memaksimalkan penyimpanan barang. Ukuran pintu dan jendela dibuat besar dengan lengkungan bata di atasnya agar pergerakan barang lebih mudah. Atapnya memiliki kemiringan curam yang khas dari arsitektur di daerah tropis supaya air hujan bisa mengalir dengan baik. Saat ini, kondisi fisik bangunan ini baik, di mana tampilan asli, tekstur bata yang tua, dan nilai keasliannya tetap terjaga dengan baik meskipun sekarang digunakan sebagai kafe dan tempat rekreasi air. </p></body></html>"},"geometry":{"type":"Point","coordinates":[100.360336099999884,-0.96395556]}}]}